import * as THREE from 'three';
import { createFloorBrowser } from './floor-browser.js';
import { OrbitControls } from './vendor/OrbitControls.js';
import { buildCampus, campusBuildings, campusDevices, campusView } from './campus-model.js';

const $ = s => document.querySelector(s);
const $$ = s => [...document.querySelectorAll(s)];
const reducedMotion = matchMedia('(prefers-reduced-motion: reduce)').matches;
const buildingData = campusBuildings;
const devices = campusDevices;
const alerts=[
 {id:'A01',title:'消防通道异常占用',level:'urgent',time:'11:42:08',location:'2号楼 · 外围消防通道',device:'F01',desc:'演示算法检测到消防通道内有车辆停留，建议派遣附近巡逻组核查并疏导。',done:false},
 {id:'A02',title:'重点区域人员聚集',level:'normal',time:'11:38:25',location:'1号楼 · 入口大厅',device:'C01',desc:'演示算法检测到大厅人员密度升高，建议安排工作人员引导分流。',done:false},
 {id:'A03',title:'周界入侵预警',level:'normal',time:'11:35:16',location:'9号楼 · 西侧周界',device:'C09',desc:'演示算法检测到周界防护区域存在异常活动，请通过关联摄像头复核。',done:false}
];
let activeFilter='all',selectedDevice=null,selectedBuilding=null,wireframe=false,routeVisible=false;
let scene,camera,renderer,controls,routeGroup,animationId,flight=null,viewportFit=1,modelController,planColors=false,floorBrowser;
const container=$('#scene'), labelContainer=$('#labels');
const buildingMeshes=[],buildingGroups=[], pins=[],buildingLabels=[], previewImages={};
const types={camera:{name:'视频监控',symbol:'◉',color:0x44e2ef},door:{name:'智能门禁',symbol:'▥',color:0x6599ff},fire:{name:'消防感知',symbol:'♧',color:0xffae5c},patrol:{name:'安保巡更',symbol:'⌖',color:0x54dbaf}};

function clock(){const now=new Date();const time=now.toLocaleTimeString('zh-CN',{hour12:false,timeZone:'Asia/Shanghai'});$('#clock').textContent=time;$('#syncTime').textContent=time;$('#date').textContent=now.toLocaleDateString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit',weekday:'long',timeZone:'Asia/Shanghai'}).replaceAll('/','.');}clock();setInterval(clock,1000);
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4200);}
function openModal(title,body){$('#detail').hidden=true;$('#modalTitle').textContent=title;$('#modalBody').innerHTML=body;$('#modal').hidden=false;document.body.style.overflow='hidden';$('#modalClose').focus();}
function closeModal(){$('#modal').hidden=true;document.body.style.overflow=$('.scene-panel').classList.contains('model-focused')?'hidden':'';}
$('#modalClose').onclick=closeModal;$('#modal').onclick=e=>{if(e.target===$('#modal'))closeModal();};window.addEventListener('keydown',e=>{if(e.key!=='Escape')return;if(!$('#modal').hidden)closeModal();else if(!$('#detail').hidden)$('#detail').hidden=true;else if(floorBrowser?.active){floorBrowser.exit();reset();}else if($('.scene-panel').classList.contains('model-focused'))$('#modelFocus').click();});

function init(){
 scene=new THREE.Scene();scene.background=new THREE.Color(0x081522);scene.fog=new THREE.FogExp2(0x081522,.00085);
 camera=new THREE.PerspectiveCamera(40,1,.1,1500);camera.position.copy(campusView.overview.position);
 renderer=new THREE.WebGLRenderer({antialias:true,alpha:false,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.35;container.appendChild(renderer.domElement);renderer.domElement.setAttribute('aria-label','依据院区效果图与总平面图重建的三维模型，拖拽旋转，滚轮缩放，点击楼栋编号或设备查看');
 controls=new OrbitControls(camera,renderer.domElement);controls.target.copy(campusView.overview.target);controls.enableDamping=true;controls.dampingFactor=.055;controls.minDistance=95;controls.maxDistance=850;controls.maxPolarAngle=Math.PI/2.2;controls.minPolarAngle=0;controls.enablePan=true;controls.autoRotateSpeed=.45;
 scene.add(new THREE.AmbientLight(0x9dbdd6,2));const sun=new THREE.DirectionalLight(0xd7edff,3.4);sun.position.set(-80,150,80);scene.add(sun);const fill=new THREE.DirectionalLight(0x238ad5,2);fill.position.set(70,40,-90);scene.add(fill);
 modelController=buildCampus(scene,{buildingMeshes,buildingGroups});
 // Device foundations and an animated emergency beacon.
 for(const d of devices){const col=types[d.type].color;const mesh=new THREE.Mesh(new THREE.CylinderGeometry(.65,.65,.8,10),new THREE.MeshBasicMaterial({color:col}));mesh.position.set(d.position.x,.6,d.position.z);scene.add(mesh);const ring=new THREE.Mesh(new THREE.RingGeometry(1.7,2,28),new THREE.MeshBasicMaterial({color:col,transparent:true,opacity:.35,side:THREE.DoubleSide}));ring.rotation.x=-Math.PI/2;ring.position.set(d.position.x,.26,d.position.z);scene.add(ring);}
 routeGroup=new THREE.Group();const routePoints=[[-95,.8,42],[-95,.8,84],[92,.8,84],[109,.8,62],[109,.8,-62],[81,.8,-70],[-88,.8,-70],[-95,.8,-42],[-95,.8,42]];const geo=new THREE.BufferGeometry().setFromPoints(routePoints.map(p=>new THREE.Vector3(...p)));const route=new THREE.Line(geo,new THREE.LineDashedMaterial({color:0x50f0c0,dashSize:3,gapSize:2,transparent:true,opacity:.9}));route.computeLineDistances();routeGroup.add(route);routeGroup.visible=false;scene.add(routeGroup);
 floorBrowser=createFloorBrowser({scene,camera,controls,meshes:buildingMeshes,host:$('.scene-panel'),onExit:reset,onFocus:()=>{flight=null;controls.autoRotate=false;$('#autoRotate').classList.remove('active');$('#autoRotate').setAttribute('aria-pressed','false');},onDevice:(d,type)=>openModal(`${d.building.toUpperCase().replace('B','')}号楼 · ${d.floor}F · ${type}`,`<span class="tag-blue">楼层演示点位</span><div class="modal-info"><div><span>点位编号</span>${d.id}</div><div><span>所属楼层</span>${d.floor}F</div><div><span>点位类型</span>${type}</div><div><span>状态</span>演示在线</div><div><span>模型坐标 X / Z</span>${d.x.toFixed(1)} / ${d.z.toFixed(1)}</div></div><p>当前点位绑定至此楼栋与楼层，展开或隔离楼层时保持相同相对位置。坐标为模型示意单位；实际点位需以现场设备台账及楼层平面校准。</p>`)});
 makeLabels();new ResizeObserver(resize).observe(container);resize();
 const raycaster=new THREE.Raycaster();let down;renderer.domElement.addEventListener('pointerdown',e=>down=[e.clientX,e.clientY]);renderer.domElement.addEventListener('pointerup',e=>{if(!down||Math.hypot(e.clientX-down[0],e.clientY-down[1])>5)return;const rect=container.getBoundingClientRect();raycaster.setFromCamera(new THREE.Vector2((e.clientX-rect.left)/rect.width*2-1,-(e.clientY-rect.top)/rect.height*2+1),camera);if(floorBrowser.pick(raycaster))return;const hit=raycaster.intersectObjects(buildingMeshes)[0];if(hit)selectBuilding(hit.object.userData.building);else $('#detail').hidden=true;});controls.addEventListener('start',()=>{flight=null;});
 $('#sceneLoading').hidden=true;generatePreviews();animate();
}
function makeLabels(){for(const b of buildingData){const el=document.createElement('button');el.className='building-label';el.innerHTML=`<b>${b.number}</b><span>号楼</span>`;el.title=b.description;el.onclick=()=>selectBuilding(b);labelContainer.appendChild(el);buildingLabels.push({el,position:new THREE.Vector3(b.id==='b2'?-7:b.x,b.h+6,b.id==='b2'?2:b.z),b});}
 for(const d of devices){const el=document.createElement('button');el.className=`map-point ${d.type}${alerts.some(a=>a.device===d.id)?' alarm':''}`;el.textContent=types[d.type].symbol;el.title=d.name;el.setAttribute('aria-label',d.name);el.onclick=e=>{e.stopPropagation();selectDevice(d);};labelContainer.appendChild(el);pins.push({el,d,position:d.position,visible:true});}}
const temp=new THREE.Vector3();function updateLabels(){const w=container.clientWidth,h=container.clientHeight,occupied=[];for(const item of [...[...buildingLabels].sort((a,b)=>b.b.h-a.b.h),...pins]){if(item.d&&!item.visible){item.el.hidden=true;continue;}temp.copy(item.position).project(camera);item.el.hidden=temp.z>1||temp.z<-1;let x=(temp.x*.5+.5)*w,y=(-temp.y*.5+.5)*h;const anchorY=y;if(item.b&&!item.el.hidden){const rw=item.el.offsetWidth||48,rh=item.el.offsetHeight||27;for(let attempt=0;attempt<4;attempt++){if(!occupied.some(r=>Math.abs(r.x-x)<(r.w+rw)/2+4&&Math.abs(r.y-y)<(r.h+rh)/2+5))break;y-=rh+6;}occupied.push({x,y,w:rw,h:rh});item.el.style.setProperty('--leader-height',`${anchorY-y+12}px`);}item.el.style.left=`${x}px`;item.el.style.top=`${y}px`;}}
function resize(){const w=container.clientWidth,h=container.clientHeight;if(!w||!h)return;flight=null;const fit=w/h<1?1.3:1;camera.position.sub(controls.target).multiplyScalar(fit/viewportFit).add(controls.target);viewportFit=fit;camera.aspect=w/h;camera.updateProjectionMatrix();renderer.setSize(w,h);}
function animate(){animationId=requestAnimationFrame(animate);if(document.hidden)return;if(flight){const t=Math.min((performance.now()-flight.start)/1000,1),ease=1-Math.pow(1-t,3);camera.position.lerpVectors(flight.from,flight.to,ease);controls.target.lerpVectors(flight.targetFrom,flight.target,ease);if(t===1)flight=null;}controls.update();renderer.render(scene,camera);updateLabels();floorBrowser?.update();}
function flyTo(position,distance=145){distance*=viewportFit;controls.autoRotate=false;$('#autoRotate').classList.remove('active');$('#autoRotate').setAttribute('aria-pressed','false');const target=new THREE.Vector3(position.x,Math.max(position.y*.3,5),position.z);const to=target.clone().add(new THREE.Vector3(-distance*.85,distance*.95,-distance*.95));if(reducedMotion){camera.position.copy(to);controls.target.copy(target);}else flight={from:camera.position.clone(),to,targetFrom:controls.target.clone(),target,start:performance.now()};}
function selectBuilding(b){selectedDevice=null;pins.forEach(p=>p.el.classList.remove('selected'));selectedBuilding=b;buildingLabels.forEach(x=>x.el.classList.toggle('selected',x.b===b));$('#buildingSelect').innerHTML=`${b.name} <span>⌄</span>`;$('#detail').hidden=true;floorBrowser.enter(b);}

function selectDevice(d){floorBrowser?.exit();const layer=$(`[data-layer="${d.type}"]`);if(!layer.classList.contains('active'))layer.click();selectedBuilding=null;buildingLabels.forEach(p=>p.el.classList.remove('selected'));$('#buildingSelect').innerHTML='全院区视图 <span>⌄</span>';selectedDevice=d;pins.forEach(p=>p.el.classList.toggle('selected',p.d===d));flyTo(d.position,115);const a=alerts.find(a=>a.device===d.id&&!a.done);$('#detail').innerHTML=`<button class="close-detail" aria-label="关闭详情">×</button><span class="tiny">${types[d.type].name} · ${d.id}</span><h3>${d.name}</h3><span class="detail-status" style="${a?'color:#ffb282':''}">● ${a?'存在待处理告警':'设备运行正常'}</span><p>所属区域：${buildingData.find(b=>b.id===d.building).name}<br>设备状态：在线 · 演示点位<br>最近同步：${$('#clock').textContent}</p><button class="detail-action">${a?'查看告警详情':d.type==='camera'?'打开模拟画面':d.type==='patrol'?'查看巡更任务':'查看设备详情'}</button>`;$('#detail').hidden=false;$('.close-detail').onclick=()=>$('#detail').hidden=true;$('.detail-action').onclick=()=>a?showAlarm(a):d.type==='camera'?showCamera(d):showDevice(d);}
function reset(){floorBrowser?.exit();selectedDevice=null;pins.forEach(p=>p.el.classList.remove('selected'));selectedBuilding=null;$('#detail').hidden=true;buildingLabels.forEach(x=>x.el.classList.remove('selected'));$('#buildingSelect').innerHTML='全院区视图 <span>⌄</span>';setView('overview');}
function generatePreviews(){const oldPos=camera.position.clone(),oldTarget=controls.target.clone();const oldQuaternion=camera.quaternion.clone();const oldAspect=camera.aspect;const oldSize=new THREE.Vector2();renderer.getSize(oldSize);renderer.setSize(480,270,false);camera.aspect=480/270;camera.updateProjectionMatrix();const shots=devices.map(d=>{const b=buildingData.find(b=>b.id===d.building);const target=new THREE.Vector3(d.position.x,Math.min(d.position.y,b.h),d.position.z);return [d.id,target.clone().add(new THREE.Vector3(-55,45,60)),target];});for(const [id,pos,target] of shots){camera.position.copy(pos);camera.lookAt(target);renderer.render(scene,camera);previewImages[id]=renderer.domElement.toDataURL('image/jpeg',.85);}camera.position.copy(oldPos);camera.quaternion.copy(oldQuaternion);controls.target.copy(oldTarget);camera.aspect=oldAspect;camera.updateProjectionMatrix();renderer.setSize(oldSize.x,oldSize.y);renderMonitors();}
function renderMonitors(){$('#monitors').innerHTML=['C01','C03','C04','C08'].map(id=>{const d=devices.find(d=>d.id===id);return `<button class="monitor" data-camera="${id}" aria-label="查看${d.name}"><img src="${previewImages[id]}" alt="${d.name}三维模拟视角"><span class="monitor-live"><i></i>SIMULATION</span><span class="monitor-expand">⛶</span><span class="monitor-name">${d.name}</span></button>`;}).join('');$$('[data-camera]').forEach(b=>b.onclick=()=>showCamera(devices.find(d=>d.id===b.dataset.camera)));}
function getPreview(d){return previewImages[d.id];}
function showCamera(d){openModal(`${d.name} · ${d.id}`,`<img class="preview" src="${getPreview(d)}" alt="${d.name}三维模拟画面"><div class="preview-caption"><span>● 三维模拟画面 · 未接入真实视频</span><span>${$('#clock').textContent}</span></div><div class="modal-info"><div><span>区域</span>${buildingData.find(b=>b.id===d.building).name}</div><div><span>设备编号</span>YC-CAM-${d.id.slice(1).padStart(3,'0')}</div><div><span>状态</span>演示在线</div><div><span>视频源</span>参考图重建模型模拟视角</div></div><p style="font-size:11px">此页面展示点位与监控的联动方式。真实部署时可在此接入视频平台的实时流与录像回放。</p>`);}
function showDevice(d){const isPatrol=d.type==='patrol';openModal(d.name,`<div class="modal-info"><div><span>设备类型</span>${types[d.type].name}</div><div><span>编号</span>YC-${d.id}</div><div><span>所属区域</span>${buildingData.find(b=>b.id===d.building).name}</div><div><span>运行状态</span>正常（演示）</div></div>${isPatrol?'<h3>当前巡更任务</h3><p>1号楼入口 → 2号楼外围 → 3/5/6号楼东侧 → 跨河连廊 → 沿街广场</p><p>最近打卡：11:39 · 下次计划：11:55<br>该巡更信息为演示数据。</p>':'<h3>设备最近记录</h3><p>11:40　设备心跳正常<br>11:30　设备自检通过<br>11:00　状态同步完成</p><p>以上为演示记录。</p>'}`);}
function showBuildingDevices(id){const list=devices.filter(d=>d.building===id);openModal(`${buildingData.find(b=>b.id===id).name} · 全部设备`,`<p>共 ${list.length} 个演示点位</p><div class="modal-grid">${list.map(d=>`<button class="camera-option" data-building-device="${d.id}">${d.name}<small>${types[d.type].name} · ${d.id}</small></button>`).join('')}</div>`);$$('[data-building-device]').forEach(el=>el.onclick=()=>{closeModal();selectDevice(devices.find(d=>d.id===el.dataset.buildingDevice));});}
function showCameraList(building){const cams=devices.filter(d=>d.type==='camera'&&(!building||d.building===building));openModal(building?`${buildingData.find(b=>b.id===building).name} · 关联摄像头`:'视频监控 · 设备列表',`<p style="font-size:11px">选择摄像头查看关联的三维模拟视角，共 ${cams.length} 个演示点位。</p><div class="modal-grid">${cams.map(d=>`<button class="camera-option" data-modal-camera="${d.id}">◉　${d.name}<small>YC-CAM-${d.id.slice(1).padStart(3,'0')}　·　在线</small></button>`).join('')}</div>`);$$('[data-modal-camera]').forEach(b=>b.onclick=()=>showCamera(devices.find(d=>d.id===b.dataset.modalCamera)));}
function renderAlerts(){const list=alerts.filter(a=>!a.done&&(activeFilter==='all'||a.level===activeFilter));$('#alertList').innerHTML=list.length?list.map(a=>`<article class="alarm-item" data-alarm="${a.id}" tabindex="0" role="button" aria-label="定位${a.title}"><div class="alarm-topline"><span class="alarm-level ${a.level==='normal'?'normal':''}">${a.level==='urgent'?'紧急告警':'一般告警'}</span><time class="alarm-time">${a.time}</time></div><h3>${a.title}</h3><span class="alarm-location">${a.location}</span><div class="alarm-actions"><span>AI 智能识别 · 演示</span><button data-handle="${a.id}">查看处置 ↗</button></div></article>`).join(''):'<div class="empty-state">✓ 暂无待处理告警<br><small>该分类下的告警已全部处置</small></div>';$$('[data-alarm]').forEach(el=>{const action=()=>{const a=alerts.find(a=>a.id===el.dataset.alarm);selectDevice(devices.find(d=>d.id===a.device));};el.onclick=action;el.onkeydown=e=>{if(e.target===el&&(e.key==='Enter'||e.key===' ')){e.preventDefault();action();}};});$$('[data-handle]').forEach(el=>el.onclick=e=>{e.stopPropagation();showAlarm(alerts.find(a=>a.id===el.dataset.handle));});const remain=alerts.filter(a=>!a.done).length;$('#alarmCount').innerHTML=`${String(remain).padStart(2,'0')}<small>起</small>`;$('#alertBadge').textContent=`${remain} 待处理`;$('#resolvedCount').innerHTML=`${String(12-remain).padStart(2,'0')}<small>起</small>`;$('#allAlarmNumber').textContent=remain;$$('.alarm-tabs button')[1].innerHTML=`紧急 <b>${alerts.filter(a=>!a.done&&a.level==='urgent').length}</b>`;$$('.alarm-tabs button')[2].innerHTML=`一般 <b>${alerts.filter(a=>!a.done&&a.level==='normal').length}</b>`;$('#disposeRate').textContent=((12-remain)/12*100).toFixed(1)+'%';pins.forEach(p=>p.el.classList.toggle('alarm',alerts.some(a=>a.device===p.d.id&&!a.done)));}
function showAlarm(a){const d=devices.find(d=>d.id===a.device);openModal(a.title,`<div class="modal-info"><div><span>告警级别</span>${a.level==='urgent'?'紧急':'一般'}</div><div><span>发生时间</span>${a.time}</div><div><span>位置</span>${a.location}</div><div><span>关联点位</span>${a.device}</div></div><p>${a.desc}</p><img class="preview" style="max-height:230px;object-fit:cover" src="${getPreview(d)}" alt="告警区域三维示意"><div class="preview-caption">关联区域模拟画面 · 演示告警</div><label for="handleNote">处置备注</label><textarea id="handleNote" placeholder="填写现场核查结果或处置措施…"></textarea><button class="modal-primary" id="resolveAlarm">确认完成处置</button>`);$('#resolveAlarm').onclick=()=>{if(!$('#handleNote').value.trim()){toast('请填写处置备注后确认');$('#handleNote').focus();return;}a.done=true;a.note=$('#handleNote').value;renderAlerts();closeModal();toast('演示告警已处置，院区态势已更新');};}

function setView(name){floorBrowser?.exit();const view=campusView[name],target=view.target.clone(),to=view.position.clone().sub(target).multiplyScalar(viewportFit).add(target);controls.autoRotate=false;$('#autoRotate').classList.remove('active');$('#autoRotate').setAttribute('aria-pressed','false');if(reducedMotion){camera.position.copy(to);controls.target.copy(target);}else flight={from:camera.position.clone(),to,targetFrom:controls.target.clone(),target,start:performance.now()};$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===name));}
$$('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));
$('#planColors').onclick=()=>{planColors=!planColors;modelController.setPlanColors(planColors);$('#planColors').classList.toggle('active',planColors);$('#planColors').setAttribute('aria-pressed',planColors);};
$('#modelFocus').onclick=()=>{const focused=$('.scene-panel').classList.toggle('model-focused');$('#modelFocus').setAttribute('aria-pressed',focused);$('#modelFocus').textContent=focused?'收起模型 ⤡':'放大模型 ⤢';document.body.style.overflow=focused?'hidden':'';};

$('#referenceImages').onclick=()=>openModal('院区模型 · 参考图对照',`<p class="reference-intro">按你提供的总平面图确定楼栋编号和组团关系，按鸟瞰效果图重建圆角轮廓、横向层带、绿色屋面、庭院与连廊。</p><div class="reference-tabs"><a href="./assets/campus-render.png" target="_blank" rel="noopener">查看高清效果图 ↗</a><a href="./assets/campus-plan.png" target="_blank" rel="noopener">查看高清总平面图 ↗</a></div><img class="reference-image" src="./assets/campus-render.png" alt="用户提供的医院东南角日景鸟瞰效果图"><img class="reference-image plan-image" src="./assets/campus-plan.png" alt="用户提供的越城院区总平面图，包含1、2、3、5、6、7、8、9、10号楼"><div class="reference-notes"><b>已按图重建</b><p>1号楼弧形主楼；2号楼中央庭院裙房；3、5、6号楼平行排布；7、8、9号楼独立组团；10号楼小型附属体；跨河连廊、沿街道路与景观水系。</p><b>建模精度</b><p>这是依据图片比例重建的外观模型，尺寸、层数和室内结构尚未经过CAD/BIM核验。总平面图没有标出4号楼，因此未补造。设备点位仍为演示配置。</p></div>`);

$$('.alarm-tabs button').forEach(b=>b.onclick=()=>{activeFilter=b.dataset.filter;$$('.alarm-tabs button').forEach(x=>x.classList.toggle('active',x===b));renderAlerts();});
$$('.layer').forEach(b=>b.onclick=()=>{b.classList.toggle('active');b.setAttribute('aria-pressed',b.classList.contains('active'));pins.filter(p=>p.d.type===b.dataset.layer).forEach(p=>p.visible=b.classList.contains('active'));});
$('#zoomIn').onclick=()=>{flight=null;camera.position.sub(controls.target).multiplyScalar(.85).add(controls.target);};$('#zoomOut').onclick=()=>{flight=null;camera.position.sub(controls.target).multiplyScalar(1.15).add(controls.target);};$('#resetView').onclick=reset;
$('#autoRotate').onclick=()=>{flight=null;controls.autoRotate=!controls.autoRotate;$('#autoRotate').classList.toggle('active',controls.autoRotate);$('#autoRotate').setAttribute('aria-pressed',controls.autoRotate);};
$('#viewToggle').onclick=()=>{wireframe=!wireframe;modelController.setWireframe(wireframe);$('#viewToggle span').textContent=wireframe?'线框透视':'建筑实体';};
$('#buildingSelect').onclick=()=>{openModal('选择楼栋视图',`<div class="modal-grid"><button class="camera-option" id="selectAll">全院区视图<small>查看院区整体态势</small></button>${buildingData.map(b=>`<button class="camera-option" data-select-building="${b.id}">${b.name}<small>${b.description} · 点击定位</small></button>`).join('')}</div>`);$('#selectAll').onclick=()=>{closeModal();reset();};$$('[data-select-building]').forEach(el=>el.onclick=()=>{closeModal();selectBuilding(buildingData.find(b=>b.id===el.dataset.selectBuilding));});};
$('#allCameras').onclick=()=>showCameraList();
function toggleRoute(force){floorBrowser?.exit();routeVisible=force??!routeVisible;routeGroup.visible=routeVisible;$('#patrolRoute').textContent=routeVisible?'⌁ 隐藏巡更路线':'⌁ 查看巡更路线';let el=$('.route-notice');if(routeVisible){if(!el){el=document.createElement('div');el.className='route-notice';el.textContent='● 一号巡逻组 · 院区环线 · 约 1.2 km（演示）';$('.scene-panel').appendChild(el);}reset();toast('巡更路线已显示，绿色虚线为计划路径');}else el?.remove();}
$('#patrolRoute').onclick=()=>toggleRoute();$$('[data-patrol]').forEach(el=>el.onclick=()=>selectDevice(devices.find(d=>d.id===`P0${Number(el.dataset.patrol)+1}`)));
$$('[data-nav]').forEach(b=>b.onclick=()=>{$$('[data-nav]').forEach(x=>x.classList.toggle('active',b===x));if(b.dataset.nav==='video'){showCameraList();}else if(b.dataset.nav==='patrol'){toggleRoute(true);}else if(b.dataset.nav==='fire'){const btn=$('[data-layer="fire"]');if(!btn.classList.contains('active'))btn.click();selectDevice(devices.find(d=>d.id==='F01'));}else reset();});
$('#dispatch').onclick=()=>{openModal('安保力量调度',`<p style="font-size:12px">创建演示调度任务。提交后会在本页面显示任务结果。</p><label for="dispatchTeam">执行巡逻组</label><select id="dispatchTeam"><option>一号巡逻组 · 1 / 2号楼区域</option><option>二号巡逻组 · 3 / 5 / 6号楼区域</option><option>三号巡逻组 · 7 / 8 / 9号楼区域</option></select><label for="dispatchTarget">任务区域</label><select id="dispatchTarget">${buildingData.map(b=>`<option>${b.name}</option>`).join('')}<option>西侧周界</option></select><label for="dispatchNote">任务说明</label><textarea id="dispatchNote" placeholder="请输入需要核查或处理的事项…"></textarea><button class="modal-primary" id="sendDispatch">下发演示任务</button>`);$('#sendDispatch').onclick=()=>{const note=$('#dispatchNote').value.trim();if(!note){toast('请填写任务说明');$('#dispatchNote').focus();return;}const team=$('#dispatchTeam').value,target=$('#dispatchTarget').value;openModal('调度任务已创建',`<div class="empty-state">✓ 演示任务创建成功</div><div class="modal-info"><div><span>执行组</span>${team}</div><div><span>目标区域</span>${target}</div><div><span>任务状态</span>待接单</div><div><span>创建时间</span>${$('#clock').textContent}</div></div><h3>任务说明</h3><p id="dispatchResult"></p><p style="font-size:11px">演示任务仅在当前页面展示，未发送至真实人员或业务平台。</p>`);$('#dispatchResult').textContent=note;};};
$('#plan').onclick=()=>{openModal('应急处置预案 · 演示',`<p style="font-size:11px">以下展示平台预案交互流程。实际处置请遵循院区正式应急预案。</p><label for="planSelect">预案类型</label><select id="planSelect"><option value="fire">消防通道异常占用</option><option value="crowd">重点区域人员聚集</option><option value="intrusion">周界异常活动</option></select><div id="planSteps"></div>`);const plans={fire:[['核实告警','通过关联视频与现场巡逻确认通道占用情况。'],['调度处置','通知就近巡逻组到场，联系车主，疏导车辆。'],['恢复复核','确认通道恢复畅通，记录现场结果并完成闭环。']],crowd:[['确认区域','查看关联画面，核实聚集规模与原因。'],['分流引导','调度附近工作人员协助维持秩序与引导分流。'],['持续观察','关注人员密度变化，确认通行恢复有序。']],intrusion:[['视频复核','调取周界关联摄像头，确认异常活动。'],['现场核查','通知就近巡逻组按院区制度进行现场核查。'],['结果记录','记录核查结果并复核设备状态。']]};function update(){const p=plans[$('#planSelect').value];$('#planSteps').innerHTML=p.map(([t,c],i)=>`<div class="plan-step"><b>0${i+1}</b><div><strong>${t}</strong><p>${c}</p></div></div>`).join('');}$('#planSelect').onchange=update;update();};
$('#fullscreen').onclick=async()=>{try{if(!document.fullscreenElement)await document.documentElement.requestFullscreen();else await document.exitFullscreen();}catch{toast('当前窗口不支持全屏，请在浏览器中打开页面');}};
renderAlerts();
try{init();}catch(err){console.error(err);$('#sceneLoading').textContent='三维场景加载失败，请使用支持 WebGL 的浏览器刷新重试';}
